css:
#adzak-sakura-storefront-app {
  position: relative;
  z-index: 50;
  width: 100%;
  min-height: 100vh;
  background-color: #fff8fb;
  background-image:
    radial-gradient(ellipse 75% 45% at 12% 4%, #ffe3ef 0%, rgba(255, 227, 239, 0) 65%),
    radial-gradient(ellipse 65% 40% at 88% 8%, #ffeaf4 0%, rgba(255, 234, 244, 0) 65%);
  color: #271322;
  font-family: 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, sans-serif;
  direction: ltr !important;
  text-align: left;
  overflow-x: hidden;
}
.modal-backdrop { z-index: 99990 !important; }
.toast-stack { z-index: 99995 !important; }
.kiko-floating-dock { z-index: 99980 !important; }

:root {
  --bg-base: #fff8fb;
  --bg-surface: #ffffff;
  --bg-elevated: #fff0f6;
  --bg-subtle: #fde2ee;

  --border-dim: #f5d4e3;
  --border-strong: #ebb4cd;

  --text-primary: #271322;
  --text-secondary: #6c4d63;
  --text-muted: #9c7c92;

  --sakura-primary: #e11d74;
  --sakura-hover: #c51362;
  --sakura-soft: #f472b6;
  --sakura-glow: rgba(225, 29, 116, 0.22);

  --brand-emerald: #059669;
  --brand-emerald-soft: #e6f9f1;
  --brand-gold: #f59e0b;

  --radius-sm: 10px;
  --radius-md: 16px;
  --radius-lg: 24px;

  --shadow-card: 0 14px 36px rgba(190, 62, 120, 0.08);
  --shadow-card-hover: 0 22px 48px rgba(190, 62, 120, 0.16);

  --font-display: 'Syne', -apple-system, BlinkMacSystemFont, sans-serif;
  --font-sans: 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, sans-serif;
  --font-mono: 'JetBrains Mono', monospace;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  margin: 0;
  background-color: var(--bg-base);
  background-image:
    radial-gradient(ellipse 75% 45% at 12% 4%, #ffe3ef 0%, rgba(255, 227, 239, 0) 65%),
    radial-gradient(ellipse 65% 40% at 88% 8%, #ffeaf4 0%, rgba(255, 234, 244, 0) 65%);
  color: var(--text-primary);
  font-family: var(--font-sans);
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
}

img {
  max-width: 100%;
  display: block;
  user-select: none;
  -webkit-user-drag: none;
}

button,
input,
select {
  font-family: inherit;
}

button {
  appearance: none;
  -webkit-appearance: none;
  background: var(--bg-elevated);
  color: var(--text-primary);
  border: 1px solid var(--border-strong);
  border-radius: var(--radius-sm);
  cursor: pointer;
}

a {
  color: inherit;
  text-decoration: none;
}

[hidden] {
  display: none !important;
}

.container {
  width: 100%;
  max-width: 1320px;
  margin: 0 auto;
  padding: 0 24px;
}

/* =========================================
   SAKURA ANNOUNCEMENT BAR & HEADER
   ========================================= */
.announcement-bar {
  background: linear-gradient(90deg, #e11d74 0%, #ec4899 50%, #db2777 100%);
  font-size: 13px;
  padding: 9px 0;
  color: #ffffff;
}

.announcement-inner {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  text-align: center;
}

.sakura-mini-flower {
  font-size: 15px;
  line-height: 1;
}

.inline-code-btn {
  background: rgba(255, 255, 255, 0.22);
  color: #ffffff;
  border: 1px dashed rgba(255, 255, 255, 0.75);
  border-radius: 6px;
  font-family: var(--font-mono);
  font-size: 12px;
  font-weight: 700;
  padding: 2px 9px;
}

.inline-code-btn:hover {
  background: #ffffff;
  color: var(--sakura-primary);
}

.site-header {
  position: sticky;
  top: 0;
  z-index: 60;
  background: rgba(255, 250, 252, 0.9);
  backdrop-filter: blur(16px);
  border-bottom: 1px solid var(--border-dim);
}

.header-inner {
  height: 72px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
}

.brand-logo {
  display: flex;
  align-items: center;
  gap: 12px;
}

.brand-emblem {
  width: 44px;
  height: 44px;
  border-radius: 13px;
  background: linear-gradient(135deg, #ffe4ef 0%, #fbcfe8 100%);
  border: 1.5px solid #f472b6;
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: 0 6px 16px rgba(236, 72, 153, 0.18);
}

.brand-text {
  display: flex;
  flex-direction: column;
  line-height: 1.15;
}

.brand-text strong {
  font-family: var(--font-display);
  font-size: 18px;
  letter-spacing: 0.03em;
  color: var(--text-primary);
}

.brand-text small {
  font-family: var(--font-mono);
  font-size: 10px;
  color: var(--sakura-primary);
  letter-spacing: 0.08em;
  font-weight: 600;
}

.main-nav {
  display: flex;
  align-items: center;
  gap: 24px;
}

.main-nav a {
  font-size: 14px;
  font-weight: 600;
  color: var(--text-secondary);
  transition: color 0.18s ease;
}

.main-nav a:hover {
  color: var(--sakura-primary);
}

.header-actions {
  display: flex;
  align-items: center;
  gap: 10px;
}

.btn-ghost-sm {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  background: var(--bg-surface);
  color: var(--text-primary);
  border: 1.5px solid var(--border-strong);
  padding: 9px 15px;
  border-radius: 999px;
  font-size: 13px;
  font-weight: 700;
  transition: all 0.18s ease;
}

.btn-ghost-sm:hover {
  background: var(--bg-elevated);
  border-color: var(--sakura-soft);
  color: var(--sakura-primary);
}

.btn-cart-header {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: linear-gradient(135deg, #e11d74 0%, #db2777 100%);
  color: #fff;
  border: none;
  padding: 9px 17px;
  border-radius: 999px;
  font-size: 13px;
  font-weight: 700;
  box-shadow: 0 8px 20px var(--sakura-glow);
  transition: transform 0.15s ease, filter 0.18s ease;
}

.btn-cart-header:hover {
  filter: brightness(1.06);
  transform: translateY(-1px);
}

.cart-count-pill {
  background: rgba(255, 255, 255, 0.25);
  color: #fff;
  padding: 2px 8px;
  border-radius: 999px;
  font-family: var(--font-mono);
  font-size: 11.5px;
}

/* =========================================
   SAKURA HERO & FLOATING PETAL ACCENTS
   ========================================= */
.store-hero {
  position: relative;
  padding: 36px 0 22px;
  overflow: hidden;
}

.sakura-branch-deco {
  position: absolute;
  top: -8px;
  right: 2%;
  width: 280px;
  height: 180px;
  pointer-events: none;
  opacity: 0.85;
}

.hero-copy-block {
  position: relative;
  z-index: 2;
  max-width: 780px;
}

.hero-kicker {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 10px;
  margin-bottom: 12px;
}

.kicker-badge {
  background: #ffe4f0;
  color: var(--sakura-primary);
  border: 1px solid #f9a8d4;
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 700;
  padding: 4px 12px;
  border-radius: 999px;
  letter-spacing: 0.05em;
}

.kicker-meta,
.kicker-sku {
  font-family: var(--font-mono);
  font-size: 11.5px;
  color: var(--text-muted);
  letter-spacing: 0.06em;
}

.store-hero h1 {
  font-family: var(--font-display);
  font-size: clamp(28px, 3.5vw, 42px);
  line-height: 1.12;
  margin: 0 0 12px;
  letter-spacing: -0.02em;
  color: var(--text-primary);
}

.sakura-accent-word {
  background: linear-gradient(120deg, #e11d74 0%, #ec4899 55%, #f43f5e 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

.store-hero p {
  margin: 0;
  font-size: 15.5px;
  color: var(--text-secondary);
  max-width: 690px;
}

.store-hero p strong {
  color: var(--text-primary);
}

.unlocked-library-bar {
  margin-top: 20px;
  background: var(--brand-emerald-soft);
  border: 1.5px solid #6ee7b7;
  border-radius: var(--radius-md);
  padding: 14px 20px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
}

.ulb-left {
  display: flex;
  align-items: center;
  gap: 12px;
}

.unlocked-check {
  width: 30px;
  height: 30px;
  border-radius: 50%;
  background: var(--brand-emerald);
  color: #ffffff;
  font-weight: 800;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.ulb-left strong {
  display: block;
  font-size: 14.5px;
  color: #064e3b;
}

.ulb-left p {
  margin: 2px 0 0;
  font-size: 12.5px;
  color: #047857;
}

.btn-download-now {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  background: var(--brand-emerald);
  color: #ffffff;
  border: none;
  font-weight: 800;
  font-size: 13.5px;
  padding: 10px 18px;
  border-radius: 999px;
}

/* =========================================
   6-PRODUCT BOUTIQUE CATALOG GRID (3 x 2)
   ========================================= */
.catalog-section {
  padding: 12px 0 58px;
}

.catalog-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
  margin-bottom: 24px;
  padding-bottom: 16px;
  border-bottom: 1px solid var(--border-dim);
}

.filter-pills {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.filter-pill {
  background: var(--bg-surface);
  color: var(--text-secondary);
  border: 1.5px solid var(--border-dim);
  padding: 8px 16px;
  border-radius: 999px;
  font-size: 13px;
  font-weight: 700;
  transition: all 0.16s ease;
}

.filter-pill:hover {
  color: var(--sakura-primary);
  border-color: var(--sakura-soft);
  background: var(--bg-elevated);
}

.filter-pill.active {
  background: linear-gradient(135deg, #e11d74 0%, #ec4899 100%);
  color: #ffffff;
  border-color: transparent;
  box-shadow: 0 6px 18px var(--sakura-glow);
}

.toolbar-hint {
  font-size: 12.5px;
  color: var(--text-muted);
}

.toolbar-hint strong {
  color: var(--sakura-primary);
}

/* 3 Columns x 2 Rows on Desktop for 6 Designs! */
.products-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 24px;
}

.product-card {
  background: var(--bg-surface);
  border: 1.5px solid var(--border-dim);
  border-radius: 22px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  box-shadow: var(--shadow-card);
  transition: border-color 0.22s ease, transform 0.22s ease, box-shadow 0.22s ease;
}

.product-card:hover {
  border-color: var(--sakura-soft);
  transform: translateY(-4px);
  box-shadow: var(--shadow-card-hover);
}

.pcard-media {
  position: relative;
  aspect-ratio: 1 / 1.02;
  overflow: hidden;
  background: #fdf2f7;
  border-bottom: 1px solid var(--border-dim);
  display: flex;
  align-items: center;
  justify-content: center;
}

.pcard-mockup-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.35s ease;
}

.product-card:hover .pcard-mockup-img {
  transform: scale(1.045);
}

.pcard-alpha-img {
  width: 82%;
  height: 84%;
  object-fit: contain;
  filter: drop-shadow(0 8px 18px rgba(39, 19, 34, 0.14));
}

.pcard-top-badges {
  position: absolute;
  top: 12px;
  left: 12px;
  z-index: 3;
}

.pcard-badge {
  display: inline-block;
  background: rgba(255, 255, 255, 0.92);
  backdrop-filter: blur(8px);
  border: 1px solid #f9a8d4;
  color: var(--sakura-primary);
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 700;
  padding: 4px 10px;
  border-radius: 999px;
  letter-spacing: 0.04em;
  box-shadow: 0 4px 12px rgba(225, 29, 116, 0.12);
}

.pcard-badge.unlocked {
  background: var(--brand-emerald);
  color: #ffffff;
  border-color: var(--brand-emerald);
}

/* Segmented Toggle on Card: Mockup vs Transparent PNG */
.pcard-mode-switch {
  position: absolute;
  bottom: 12px;
  left: 12px;
  right: 12px;
  z-index: 3;
  background: rgba(255, 255, 255, 0.92);
  backdrop-filter: blur(10px);
  border: 1px solid var(--border-strong);
  border-radius: 999px;
  padding: 3px;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 3px;
  box-shadow: 0 8px 20px rgba(39, 19, 34, 0.12);
}

.pcard-mode-btn {
  background: transparent;
  color: var(--text-secondary);
  border: none;
  font-size: 11.5px;
  font-weight: 700;
  padding: 6px 8px;
  border-radius: 999px;
  transition: all 0.15s ease;
}

.pcard-mode-btn.active {
  background: var(--sakura-primary);
  color: #ffffff;
}

/* Card Body */
.pcard-body {
  padding: 18px 20px 20px;
  display: flex;
  flex-direction: column;
  flex: 1;
}

.pcard-meta-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  font-size: 12px;
  margin-bottom: 6px;
}

.pcard-cat {
  color: var(--sakura-primary);
  font-weight: 700;
}

.pcard-rating {
  color: var(--text-secondary);
  font-weight: 600;
}

.pcard-rating .stars {
  color: var(--brand-gold);
}

.pcard-title {
  font-family: var(--font-display);
  font-size: 18px;
  line-height: 1.24;
  margin: 0 0 6px;
  color: var(--text-primary);
}

.pcard-spec-line {
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 600;
  color: var(--brand-emerald);
  margin-bottom: 8px;
}

.pcard-desc {
  color: var(--text-secondary);
  font-size: 13px;
  line-height: 1.52;
  margin: 0 0 15px;
  flex: 1;
}

.pcard-unlocked-box {
  background: var(--brand-emerald-soft);
  border: 1px solid #6ee7b7;
  border-radius: 10px;
  padding: 9px 12px;
  margin-bottom: 12px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.pcard-unlocked-box span {
  font-size: 12px;
  font-weight: 700;
  color: #065f46;
}

.pcard-dl-btn {
  background: var(--brand-emerald);
  color: #ffffff;
  font-size: 12px;
  font-weight: 800;
  padding: 6px 12px;
  border-radius: 999px;
  white-space: nowrap;
}

.pcard-price-row {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  margin-bottom: 12px;
  padding-top: 12px;
  border-top: 1px solid var(--border-dim);
}

.pcard-price-wrap {
  display: flex;
  align-items: baseline;
  gap: 8px;
}

.pcard-price {
  font-family: var(--font-display);
  font-size: 24px;
  font-weight: 800;
  color: var(--text-primary);
}

.pcard-compare {
  font-size: 13.5px;
  color: var(--text-muted);
  text-decoration: line-through;
}

.pcard-save-tag {
  font-family: var(--font-mono);
  font-size: 10.5px;
  font-weight: 700;
  color: var(--sakura-primary);
  background: #ffe4f0;
  padding: 3px 8px;
  border-radius: 999px;
}

.btn-card-buy {
  width: 100%;
  background: linear-gradient(135deg, #e11d74 0%, #ec4899 100%);
  color: #ffffff;
  border: none;
  padding: 12px 16px;
  border-radius: 12px;
  font-size: 14px;
  font-weight: 800;
  margin-bottom: 8px;
  box-shadow: 0 8px 20px var(--sakura-glow);
  transition: filter 0.16s ease, transform 0.15s ease;
}

.btn-card-buy:hover {
  filter: brightness(1.06);
  transform: translateY(-1px);
}

.pcard-secondary-btns {
  display: grid;
  grid-template-columns: 0.9fr 1.1fr;
  gap: 8px;
}

.btn-card-cart {
  background: var(--bg-elevated);
  color: var(--text-primary);
  border: 1px solid var(--border-strong);
  padding: 9px 10px;
  border-radius: 10px;
  font-size: 12.5px;
  font-weight: 700;
}

.btn-card-cart:hover {
  border-color: var(--sakura-soft);
}

.btn-card-cart.in-cart {
  background: #ffe4f0;
  border-color: var(--sakura-primary);
  color: var(--sakura-primary);
}

.btn-card-inspect {
  background: var(--bg-surface);
  color: var(--text-secondary);
  border: 1px solid var(--border-dim);
  padding: 9px 10px;
  border-radius: 10px;
  font-size: 12.5px;
  font-weight: 700;
}

.btn-card-inspect:hover {
  background: var(--bg-elevated);
  color: var(--sakura-primary);
  border-color: var(--sakura-soft);
}

/* =========================================
   COMPLETE 6-DESIGN SAKURA MEGA BUNDLE
   ========================================= */
.bundle-section {
  padding: 6px 0 64px;
}

.bundle-card {
  background: linear-gradient(135deg, #ffe6f1 0%, #fff2f8 48%, #ffeaf3 100%);
  border: 2px solid #f9a8d4;
  border-radius: 26px;
  padding: 36px;
  display: grid;
  grid-template-columns: 1.1fr 0.9fr;
  gap: 32px;
  align-items: center;
  box-shadow: 0 22px 54px rgba(225, 29, 116, 0.12);
}

.bundle-pill {
  display: inline-block;
  background: #ffffff;
  color: var(--sakura-primary);
  border: 1px solid #f472b6;
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 700;
  padding: 5px 12px;
  border-radius: 999px;
  margin-bottom: 12px;
}

.bundle-copy h2 {
  font-family: var(--font-display);
  font-size: clamp(23px, 2.7vw, 32px);
  margin: 0 0 12px;
  color: var(--text-primary);
}

.bundle-copy p {
  color: var(--text-secondary);
  font-size: 15px;
  margin: 0 0 22px;
}

.bundle-price-cta {
  display: flex;
  align-items: center;
  gap: 22px;
  flex-wrap: wrap;
}

.bundle-price-group strong {
  font-family: var(--font-display);
  font-size: 34px;
  color: var(--sakura-primary);
}

.bundle-price-group span {
  font-size: 17px;
  color: var(--text-muted);
  text-decoration: line-through;
  margin-left: 8px;
}

.bundle-price-group small {
  display: block;
  font-size: 12.5px;
  font-weight: 600;
  color: var(--brand-emerald);
}

.btn-buy-bundle {
  background: linear-gradient(135deg, #e11d74 0%, #db2777 100%);
  color: #fff;
  border: none;
  padding: 15px 24px;
  border-radius: 999px;
  font-size: 15px;
  font-weight: 800;
  box-shadow: 0 12px 28px var(--sakura-glow);
  transition: transform 0.15s ease, filter 0.15s ease;
}

.btn-buy-bundle:hover {
  transform: translateY(-2px);
  filter: brightness(1.06);
}

.bundle-thumbs-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
}

.bundle-thumb-item {
  aspect-ratio: 1 / 1.08;
  border-radius: 14px;
  border: 1.5px solid #f5c2d9;
  padding: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  box-shadow: 0 6px 16px rgba(190, 62, 120, 0.08);
}

.bundle-thumb-item img {
  max-height: 100%;
  object-fit: contain;
}

/* =========================================
   INTERACTIVE TRANSPARENCY & SHIRT STUDIO
   ========================================= */
.studio-section {
  padding: 64px 0;
  border-top: 1px solid var(--border-dim);
  background: linear-gradient(180deg, #fff3f8 0%, #fffafd 100%);
}

.studio-design-switcher {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.studio-switch-pill {
  background: var(--bg-surface);
  color: var(--text-secondary);
  border: 1.5px solid var(--border-dim);
  padding: 8px 14px;
  border-radius: 999px;
  font-size: 12.5px;
  font-weight: 700;
}

.studio-switch-pill:hover {
  border-color: var(--sakura-soft);
  color: var(--sakura-primary);
}

.studio-switch-pill.active {
  background: var(--sakura-primary);
  color: #fff;
  border-color: var(--sakura-primary);
  box-shadow: 0 6px 16px var(--sakura-glow);
}

.hero-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.05fr) minmax(0, 0.95fr);
  gap: 40px;
  align-items: start;
}

.gallery-stage-card {
  background: var(--bg-surface);
  border: 1.5px solid var(--border-dim);
  border-radius: var(--radius-lg);
  padding: 16px;
  box-shadow: var(--shadow-card);
}

.gallery-tabs {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
  margin-bottom: 14px;
  background: var(--bg-elevated);
  padding: 5px;
  border-radius: 999px;
  border: 1px solid var(--border-dim);
}

.gallery-tab {
  background: transparent;
  color: var(--text-secondary);
  border: none;
  padding: 10px;
  border-radius: 999px;
  font-size: 12.5px;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
}

.gallery-tab span {
  font-family: var(--font-mono);
  font-size: 11px;
  opacity: 0.65;
}

.gallery-tab.active {
  background: var(--bg-surface);
  color: var(--sakura-primary);
  box-shadow: 0 4px 12px rgba(225, 29, 116, 0.12);
}

.gallery-pane {
  display: none;
}

.gallery-pane.active {
  display: block;
}

.mockup-viewport,
.tester-viewport {
  position: relative;
  border-radius: 16px;
  overflow: hidden;
  aspect-ratio: 1 / 0.96;
  border: 1px solid var(--border-dim);
  display: flex;
  align-items: center;
  justify-content: center;
}

.mockup-viewport {
  background: #fdf2f7;
  cursor: crosshair;
}

.mockup-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.25s ease-out;
}

.mockup-viewport:hover .mockup-img {
  transform: scale(1.22);
}

.viewport-pill {
  position: absolute;
  display: inline-flex;
  align-items: center;
  gap: 7px;
  background: rgba(255, 255, 255, 0.92);
  backdrop-filter: blur(8px);
  border: 1px solid var(--border-strong);
  color: var(--text-primary);
  padding: 6px 12px;
  border-radius: 999px;
  font-size: 11.5px;
  font-weight: 700;
  pointer-events: none;
  box-shadow: 0 4px 14px rgba(39, 19, 34, 0.08);
}

.viewport-pill.top-left {
  top: 14px;
  left: 14px;
}

.viewport-pill.bottom-right {
  bottom: 14px;
  right: 14px;
  color: var(--text-secondary);
}

.viewport-pill.bottom-left {
  bottom: 14px;
  left: 14px;
  right: 14px;
  justify-content: center;
  border-radius: 10px;
}

.dot-green,
.dot-blue {
  width: 8px;
  height: 8px;
  border-radius: 50%;
}

.dot-green {
  background: var(--brand-emerald);
}

.dot-blue {
  background: var(--sakura-primary);
}

/* Checkerboards & Garment Backdrops */
.bg-checker-light,
.checker-light-box {
  background-color: #eaedf3;
  background-image:
    linear-gradient(45deg, #ffffff 25%, transparent 25%),
    linear-gradient(-45deg, #ffffff 25%, transparent 25%),
    linear-gradient(45deg, transparent 75%, #ffffff 75%),
    linear-gradient(-45deg, transparent 75%, #ffffff 75%);
  background-size: 24px 24px;
  background-position: 0 0, 0 12px, 12px -12px, -12px 0;
}

.bg-checker-dark,
.checker-dark-box {
  background-color: #191c26;
  background-image:
    linear-gradient(45deg, #272b3a 25%, transparent 25%),
    linear-gradient(-45deg, #272b3a 25%, transparent 25%),
    linear-gradient(45deg, transparent 75%, #272b3a 75%),
    linear-gradient(-45deg, transparent 75%, #272b3a 75%);
  background-size: 24px 24px;
  background-position: 0 0, 0 12px, 12px -12px, -12px 0;
}

.bg-tee-sakura,
.solid-sakura-box {
  background: radial-gradient(circle at 50% 35%, #ffe9f3 0%, #fbcfe8 88%);
}

.bg-tee-cream {
  background: radial-gradient(circle at 50% 35%, #fffdf9 0%, #f5ece0 88%);
}

.bg-tee-white,
.solid-white-box {
  background: radial-gradient(circle at 50% 35%, #ffffff 0%, #eef0f5 88%);
}

.bg-tee-terracotta {
  background: radial-gradient(circle at 50% 35%, #d67046 0%, #ad502c 88%);
}

.bg-tee-black,
.solid-black-box {
  background: radial-gradient(circle at 50% 35%, #1d202b 0%, #0b0c10 85%);
}

.garment-collar-hint {
  position: absolute;
  top: -28px;
  left: 50%;
  transform: translateX(-50%);
  width: 170px;
  height: 58px;
  border-radius: 50%;
  border: 8px solid rgba(140, 100, 125, 0.14);
  pointer-events: none;
}

.tester-png-img {
  width: 78%;
  height: 78%;
  object-fit: contain;
  filter: drop-shadow(0 6px 18px rgba(39, 19, 34, 0.15));
}

.swatch-bar {
  margin-top: 14px;
  padding-top: 12px;
  border-top: 1px solid var(--border-dim);
}

.swatch-label {
  font-size: 12px;
  font-weight: 700;
  color: var(--text-secondary);
  margin-bottom: 10px;
}

.swatch-list-7 {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  gap: 6px;
}

.swatch-btn {
  background: var(--bg-elevated);
  border: 1.5px solid var(--border-dim);
  border-radius: 12px;
  padding: 8px 3px;
  color: var(--text-secondary);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 5px;
}

.swatch-btn.active {
  border-color: var(--sakura-primary);
  background: #ffe4f0;
  color: var(--sakura-primary);
}

.swatch-chip {
  width: 24px;
  height: 24px;
  border-radius: 50%;
  border: 1px solid rgba(39, 19, 34, 0.2);
}

.swatch-chip.checker-dark {
  background-color: #161821;
  background-image: linear-gradient(45deg, #32384c 25%, transparent 25%),
    linear-gradient(-45deg, #32384c 25%, transparent 25%),
    linear-gradient(45deg, transparent 75%, #32384c 75%),
    linear-gradient(-45deg, transparent 75%, #32384c 75%);
  background-size: 10px 10px;
  background-position: 0 0, 0 5px, 5px -5px, -5px 0;
}

.swatch-chip.checker-light {
  background-color: #cbd5e1;
  background-image: linear-gradient(45deg, #ffffff 25%, transparent 25%),
    linear-gradient(-45deg, #ffffff 25%, transparent 25%),
    linear-gradient(45deg, transparent 75%, #ffffff 75%),
    linear-gradient(-45deg, transparent 75%, #ffffff 75%);
  background-size: 10px 10px;
  background-position: 0 0, 0 5px, 5px -5px, -5px 0;
}

.swatch-btn small {
  font-size: 10.5px;
  font-weight: 700;
}

/* Studio Right Panel */
.studio-kicker {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 10px;
}

.studio-prod-title {
  font-family: var(--font-display);
  font-size: clamp(24px, 2.6vw, 31px);
  line-height: 1.16;
  margin: 0 0 12px;
  color: var(--text-primary);
}

.rating-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 10px;
  font-size: 13.5px;
  margin-bottom: 14px;
}

.stars {
  color: var(--brand-gold);
  letter-spacing: 2px;
}

.instant-tag {
  color: var(--brand-emerald);
  font-weight: 700;
}

.product-lead {
  color: var(--text-secondary);
  font-size: 14.5px;
  margin: 0 0 18px;
  line-height: 1.65;
}

.studio-specs-mini {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
  background: var(--bg-surface);
  border: 1.5px solid var(--border-dim);
  border-radius: 14px;
  padding: 14px;
  margin-bottom: 20px;
}

.studio-specs-mini small {
  display: block;
  font-family: var(--font-mono);
  font-size: 10px;
  color: var(--text-muted);
}

.studio-specs-mini strong {
  font-size: 13px;
}

.section-micro-label {
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
  color: var(--text-muted);
  margin-bottom: 10px;
}

.tier-cards {
  display: flex;
  flex-direction: column;
  gap: 10px;
  margin-bottom: 20px;
}

.tier-card {
  position: relative;
  display: block;
  background: var(--bg-surface);
  border: 1.5px solid var(--border-dim);
  border-radius: var(--radius-md);
  padding: 14px 16px;
  cursor: pointer;
  transition: all 0.16s ease;
}

.tier-card input[type="radio"] {
  position: absolute;
  opacity: 0;
}

.tier-card.selected {
  border-color: var(--sakura-primary);
  background: #fff3f8;
  box-shadow: 0 8px 22px rgba(225, 29, 116, 0.08);
}

.tier-card-top {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 10px;
}

.tier-name {
  font-weight: 700;
  font-size: 14px;
}

.tier-badge {
  display: inline-block;
  margin-left: 8px;
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 700;
  padding: 2px 8px;
  border-radius: 999px;
  background: #ffe4f0;
  color: var(--sakura-primary);
}

.tier-badge.alt {
  background: #ede9fe;
  color: #7c3aed;
}

.tier-price {
  font-family: var(--font-mono);
  font-size: 16.5px;
  color: var(--sakura-primary);
}

.tier-desc {
  margin: 5px 0 0;
  font-size: 12.5px;
  color: var(--text-secondary);
}

.studio-cta-row {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.btn-buy-primary {
  width: 100%;
  background: linear-gradient(135deg, #e11d74 0%, #ec4899 100%);
  color: #fff;
  border: none;
  border-radius: var(--radius-md);
  padding: 15px 20px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 3px;
  box-shadow: 0 12px 28px var(--sakura-glow);
}

.btn-buy-main {
  font-size: 16px;
  font-weight: 800;
}

.btn-buy-sub {
  font-size: 11.5px;
  color: rgba(255, 255, 255, 0.9);
}

.btn-add-cart-lg {
  width: 100%;
  background: var(--bg-surface);
  color: var(--text-primary);
  border: 1.5px solid var(--border-strong);
  border-radius: var(--radius-md);
  padding: 12px 18px;
  font-size: 14px;
  font-weight: 700;
}

.btn-add-cart-lg:hover {
  background: var(--bg-elevated);
  border-color: var(--sakura-soft);
  color: var(--sakura-primary);
}

/* =========================================
   SPECS STRIP, REVIEWS, FAQ, FOOTER
   ========================================= */
.specs-strip-section {
  padding: 32px 0;
  border-top: 1px solid var(--border-dim);
  border-bottom: 1px solid var(--border-dim);
  background: #fff0f6;
}

.specs-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
}

.spec-box {
  background: var(--bg-surface);
  border: 1px solid var(--border-dim);
  border-radius: var(--radius-md);
  padding: 20px;
  box-shadow: var(--shadow-card);
}

.spec-mono {
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 700;
  color: var(--sakura-primary);
  letter-spacing: 0.08em;
}

.spec-box strong {
  display: block;
  font-family: var(--font-display);
  font-size: 19px;
  margin: 6px 0;
}

.spec-box p {
  margin: 0;
  font-size: 13px;
  color: var(--text-secondary);
}

.section-eyebrow {
  display: inline-block;
  font-family: var(--font-mono);
  font-size: 11.5px;
  font-weight: 700;
  letter-spacing: 0.09em;
  color: var(--sakura-primary);
  margin-bottom: 8px;
}

.section-head {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  gap: 20px;
  margin-bottom: 30px;
  flex-wrap: wrap;
}

.section-head h2 {
  font-family: var(--font-display);
  font-size: clamp(24px, 2.8vw, 32px);
  margin: 0;
}

.section-head.centered {
  flex-direction: column;
  align-items: center;
  text-align: center;
}

.reviews-section {
  padding: 68px 0;
  background: var(--bg-base);
  border-bottom: 1px solid var(--border-dim);
}

.overall-rating-pill {
  background: var(--bg-surface);
  border: 1.5px solid var(--border-strong);
  padding: 9px 16px;
  border-radius: 999px;
  font-size: 13.5px;
  font-weight: 600;
  display: flex;
  align-items: center;
  gap: 8px;
}

.reviews-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}

.review-card {
  background: var(--bg-surface);
  border: 1.5px solid var(--border-dim);
  border-radius: var(--radius-md);
  padding: 24px;
  display: flex;
  flex-direction: column;
  box-shadow: var(--shadow-card);
}

.rev-top {
  display: flex;
  justify-content: space-between;
  margin-bottom: 12px;
}

.rev-verified {
  font-size: 12px;
  color: var(--brand-emerald);
  font-weight: 700;
}

.review-card h3 {
  font-size: 16px;
  margin: 0 0 10px;
}

.review-card p {
  font-size: 14px;
  color: var(--text-secondary);
  margin: 0 0 18px;
  flex: 1;
}

.rev-author {
  font-size: 12.5px;
  color: var(--text-muted);
  border-top: 1px solid var(--border-dim);
  padding-top: 12px;
}

.faq-section {
  padding: 68px 0 80px;
}

.faq-container {
  max-width: 820px;
}

.faq-list {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.faq-item {
  background: var(--bg-surface);
  border: 1.5px solid var(--border-dim);
  border-radius: var(--radius-md);
  padding: 18px 22px;
  box-shadow: var(--shadow-card);
}

.faq-item summary {
  font-weight: 700;
  font-size: 15.5px;
  cursor: pointer;
  list-style: none;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.faq-item summary::-webkit-details-marker {
  display: none;
}

.faq-item summary::after {
  content: '+';
  font-family: var(--font-mono);
  font-size: 20px;
  color: var(--sakura-primary);
}

.faq-item[open] summary::after {
  content: '−';
}

.faq-item p {
  margin: 12px 0 0;
  color: var(--text-secondary);
  font-size: 14.5px;
}

.site-footer {
  border-top: 1px solid var(--border-dim);
  padding: 32px 0;
  background: #fff0f6;
}

.footer-inner {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 20px;
}

.footer-brand p {
  margin: 4px 0 0;
  font-size: 13px;
  color: var(--text-secondary);
}

.footer-links {
  display: flex;
  align-items: center;
  gap: 20px;
  font-size: 13.5px;
  font-weight: 600;
  color: var(--text-secondary);
}

.footer-link-btn {
  background: none;
  border: none;
  color: var(--text-secondary);
  font-size: 13.5px;
  font-weight: 600;
  padding: 0;
}

.footer-link-btn:hover,
.footer-links a:hover {
  color: var(--sakura-primary);
}

.owner-link {
  opacity: 0.75;
}

/* =========================================
   MODALS: CHECKOUT, MULTI-FILE VAULT & LOOKUP
   ========================================= */
.modal-backdrop {
  position: fixed;
  inset: 0;
  z-index: 200;
  background: rgba(58, 20, 44, 0.45);
  backdrop-filter: blur(10px);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 18px;
  overflow-y: auto;
}

.modal-card {
  width: 100%;
  background: var(--bg-surface);
  border: 2px solid var(--border-strong);
  border-radius: var(--radius-lg);
  box-shadow: 0 32px 80px rgba(131, 24, 67, 0.22);
  max-height: 92vh;
  overflow-y: auto;
}

.checkout-modal-card {
  max-width: 580px;
}

.vault-modal-card {
  max-width: 960px;
}

.lookup-modal-card {
  max-width: 460px;
}

.modal-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  padding: 22px 26px 18px;
  border-bottom: 1px solid var(--border-dim);
  background: #fff7fa;
}

.modal-kicker {
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 700;
  color: var(--sakura-primary);
  letter-spacing: 0.08em;
}

.modal-header h2 {
  font-family: var(--font-display);
  font-size: 22px;
  margin: 4px 0 0;
}

.modal-close {
  background: var(--bg-surface);
  color: var(--text-secondary);
  border: 1px solid var(--border-strong);
  width: 34px;
  height: 34px;
  border-radius: 50%;
  font-size: 22px;
  line-height: 1;
}

.modal-close:hover {
  color: var(--sakura-primary);
  border-color: var(--sakura-primary);
}

.checkout-body,
.lookup-body {
  padding: 22px 26px 26px;
}

.checkout-summary-box {
  background: #fff5f9;
  border: 1.5px solid var(--border-dim);
  border-radius: var(--radius-md);
  padding: 14px;
  margin-bottom: 20px;
}

.checkout-items-list {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.cs-item-row {
  display: flex;
  align-items: center;
  gap: 12px;
  padding-bottom: 10px;
  border-bottom: 1px solid var(--border-dim);
}

.cs-thumb {
  width: 50px;
  height: 56px;
  border-radius: 8px;
  border: 1px solid var(--border-strong);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  padding: 4px;
}

.cs-thumb img {
  max-height: 100%;
  object-fit: contain;
}

.cs-details {
  flex: 1;
}

.cs-details strong {
  display: block;
  font-size: 13.5px;
}

.cs-details small {
  font-size: 11.5px;
  color: var(--text-muted);
}

.cs-remove-btn {
  background: none;
  border: none;
  color: var(--text-muted);
  font-size: 18px;
  padding: 4px;
}

.cs-remove-btn:hover {
  color: #e11d74;
}

.checkout-total-bar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-top: 10px;
  font-weight: 700;
}

.cs-price-col {
  text-align: right;
}

.cs-price-col strong {
  display: block;
  font-family: var(--font-mono);
  font-size: 20px;
  color: var(--sakura-primary);
}

.cs-price-col small {
  color: var(--brand-emerald);
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 700;
}

.promo-row {
  display: flex;
  gap: 8px;
  margin-top: 12px;
  padding-top: 12px;
  border-top: 1px solid var(--border-dim);
}

.promo-row input {
  flex: 1;
  background: var(--bg-surface);
  border: 1px solid var(--border-strong);
  color: var(--text-primary);
  padding: 8px 12px;
  border-radius: 8px;
  font-size: 13px;
  text-transform: uppercase;
}

.promo-row button {
  background: var(--sakura-primary);
  color: #fff;
  border: none;
  border-radius: 8px;
  padding: 8px 16px;
  font-size: 13px;
  font-weight: 700;
}

.promo-feedback {
  margin-top: 8px;
  font-size: 12.5px;
  font-weight: 600;
  color: var(--brand-emerald);
}

.promo-feedback.err {
  color: #e11d74;
}

.form-row-two {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
}

.form-field {
  margin-bottom: 14px;
}

.form-field label {
  display: block;
  font-size: 12.5px;
  font-weight: 700;
  color: var(--text-secondary);
  margin-bottom: 6px;
}

.form-field input,
.form-field select {
  width: 100%;
  background: #fffafd;
  border: 1.5px solid var(--border-strong);
  color: var(--text-primary);
  padding: 11px 13px;
  border-radius: 10px;
  font-size: 14px;
}

.form-field input:focus,
.form-field select:focus {
  outline: none;
  border-color: var(--sakura-primary);
  background: #ffffff;
}

.pay-method-tabs {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
}

.pay-tab {
  background: var(--bg-elevated);
  color: var(--text-secondary);
  border: 1.5px solid var(--border-dim);
  border-radius: 10px;
  padding: 11px;
  font-size: 13.5px;
  font-weight: 700;
}

.pay-tab.active {
  border-color: var(--sakura-primary);
  color: var(--sakura-primary);
  background: #ffe4f0;
}

.card-fields-box {
  background: #fff5f9;
  border: 1px solid var(--border-dim);
  border-radius: 12px;
  padding: 14px;
  margin-bottom: 16px;
}

.card-box-top {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 10px;
  font-size: 12.5px;
  font-weight: 600;
  color: var(--text-secondary);
}

.fill-demo-btn {
  background: #ffe4f0;
  color: var(--sakura-primary);
  border: 1px solid #f472b6;
  border-radius: 999px;
  padding: 4px 12px;
  font-size: 11.5px;
