/* =========================================================
   V5.0 UPGRADE — INTERACTIVE BOSS KIKO STAGE, HARAKAT POSES,
   BOUTIQUE MARQUEE, FEATURED VIP GLOW & FLOATING COMPANION
   ========================================================= */

/* Ambient drifting Sakura petals in Hero */
.hero-ambient-petals {
  position: absolute;
  inset: 0;
  pointer-events: none;
  overflow: hidden;
  z-index: 0;
}

.ambient-petal {
  position: absolute;
  top: -30px;
  width: 15px;
  height: 11px;
  border-radius: 80% 15% 80% 15%;
  background: linear-gradient(135deg, #fbcfe8 0%, #f472b6 100%);
  opacity: 0.45;
  animation: petalDrift linear infinite;
}

.ambient-petal.p1 { left: 8%; animation-duration: 13s; animation-delay: 0s; }
.ambient-petal.p2 { left: 26%; width: 12px; height: 9px; animation-duration: 16s; animation-delay: -4s; }
.ambient-petal.p3 { left: 48%; width: 17px; height: 12px; animation-duration: 14s; animation-delay: -8s; }
.ambient-petal.p4 { left: 71%; width: 13px; height: 9px; animation-duration: 17s; animation-delay: -2s; }
.ambient-petal.p5 { left: 89%; width: 15px; height: 11px; animation-duration: 15s; animation-delay: -6s; }

@keyframes petalDrift {
  0% { transform: translate3d(0, -20px, 0) rotate(0deg); opacity: 0; }
  12% { opacity: 0.55; }
  85% { opacity: 0.45; }
  100% { transform: translate3d(-90px, 560px, 0) rotate(340deg); opacity: 0; }
}

/* 2-Column Hero Split Grid */
.hero-split-grid {
  position: relative;
  z-index: 2;
  display: grid;
  grid-template-columns: 1.08fr 0.92fr;
  gap: 36px;
  align-items: center;
}

.hero-split-grid .hero-copy-block {
  max-width: 640px;
}

.hero-cta-row {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  margin-top: 24px;
}

.btn-hero-primary {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 14px 24px;
  border-radius: 999px;
  background: linear-gradient(135deg, #e11d74 0%, #db2777 55%, #ec4899 100%);
  color: #ffffff;
  font-weight: 800;
  font-size: 14.5px;
  border: none;
  box-shadow: 0 12px 28px rgba(225, 29, 116, 0.28);
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.btn-hero-primary:hover {
  transform: translateY(-2px);
  box-shadow: 0 16px 34px rgba(225, 29, 116, 0.36);
}

.btn-hero-secondary {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 14px 22px;
  border-radius: 999px;
  background: #ffffff;
  color: var(--text-primary);
  font-weight: 800;
  font-size: 14px;
  border: 1.5px solid var(--border-strong);
  box-shadow: 0 8px 20px rgba(190, 62, 120, 0.08);
  transition: all 0.2s ease;
}

.btn-hero-secondary:hover {
  border-color: var(--sakura-primary);
  color: var(--sakura-primary);
  transform: translateY(-2px);
}

.hero-trust-pills {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
  margin-top: 24px;
}

.hero-trust-item {
  background: rgba(255, 255, 255, 0.85);
  backdrop-filter: blur(8px);
  border: 1px solid var(--border-dim);
  border-radius: 14px;
  padding: 10px 13px;
  box-shadow: 0 6px 18px rgba(190, 62, 120, 0.05);
}

.hero-trust-item strong {
  display: block;
  font-family: var(--font-display);
  font-size: 15.5px;
  color: var(--text-primary);
}

.hero-trust-item small {
  font-size: 11.5px;
  color: var(--text-secondary);
  font-weight: 600;
}

/* Interactive 3D Boss Kiko Mascot Stage */
.mascot-stage-wrap {
  perspective: 1100px;
}

.mascot-stage-card {
  position: relative;
  background:
    radial-gradient(circle at 50% 38%, rgba(251, 207, 232, 0.72) 0%, rgba(255, 240, 246, 0.5) 48%, rgba(255, 255, 255, 0.96) 100%);
  border: 1.5px solid #f2bdd6;
  border-radius: 28px;
  padding: 18px 18px 16px;
  box-shadow:
    0 24px 56px rgba(190, 62, 120, 0.14),
    inset 0 1px 0 #ffffff;
  transform-style: preserve-3d;
  transition: transform 0.18s ease-out, box-shadow 0.25s ease;
  overflow: hidden;
}

.mascot-stage-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 6px;
  position: relative;
  z-index: 4;
}

.mascot-director-tag {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: #ffffff;
  border: 1px solid var(--border-strong);
  padding: 5px 11px;
  border-radius: 999px;
  font-family: var(--font-mono);
  font-size: 10.5px;
  font-weight: 700;
  color: var(--sakura-primary);
  box-shadow: 0 4px 12px rgba(225, 29, 116, 0.08);
}

.live-pulse-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: #10b981;
  box-shadow: 0 0 0 4px rgba(16, 185, 129, 0.2);
  animation: pulseDot 1.8s infinite;
}

@keyframes pulseDot {
  0%, 100% { transform: scale(1); opacity: 1; }
  50% { transform: scale(1.25); opacity: 0.7; }
}

.mascot-autoplay-btn {
  padding: 5px 11px;
  border-radius: 999px;
  font-size: 11px;
  font-weight: 800;
  background: #ffffff;
  color: var(--text-secondary);
  border: 1px solid var(--border-strong);
  transition: all 0.18s ease;
}

.mascot-autoplay-btn.active {
  background: var(--sakura-primary);
  color: #ffffff;
  border-color: var(--sakura-primary);
}

/* Live Speech Bubble */
.mascot-speech-bubble {
  position: relative;
  z-index: 4;
  background: #ffffff;
  border: 1.5px solid #f4b8d4;
  border-radius: 16px;
  padding: 9px 14px;
  font-size: 12.8px;
  font-weight: 700;
  color: var(--text-primary);
  box-shadow: 0 10px 24px rgba(190, 62, 120, 0.1);
  margin: 4px auto 6px;
  text-align: center;
  transition: transform 0.22s cubic-bezier(0.34, 1.56, 0.64, 1), opacity 0.18s ease;
}

.mascot-speech-bubble::after {
  content: '';
  position: absolute;
  bottom: -7px;
  left: 50%;
  transform: translateX(-50%) rotate(45deg);
  width: 12px;
  height: 12px;
  background: #ffffff;
  border-right: 1.5px solid #f4b8d4;
  border-bottom: 1.5px solid #f4b8d4;
}

.mascot-speech-bubble.pop {
  transform: scale(1.04);
}

/* Character Arena */
.mascot-arena {
  position: relative;
  height: 330px;
  display: flex;
  align-items: flex-end;
  justify-content: center;
  cursor: pointer;
  user-select: none;
}

.mascot-halo-ring {
  position: absolute;
  top: 50%;
  left: 50%;
  width: 245px;
  height: 245px;
  transform: translate(-50%, -52%);
  border-radius: 50%;
  background: radial-gradient(circle, rgba(244, 114, 182, 0.28) 0%, rgba(251, 207, 232, 0.12) 58%, transparent 74%);
  border: 1.5px dashed rgba(225, 29, 116, 0.22);
  animation: slowSpinRing 24s linear infinite;
  pointer-events: none;
}

@keyframes slowSpinRing {
  from { transform: translate(-50%, -52%) rotate(0deg); }
  to { transform: translate(-50%, -52%) rotate(360deg); }
}

.mascot-floor-shadow {
  position: absolute;
  bottom: 8px;
  left: 50%;
  transform: translateX(-50%);
  width: 150px;
  height: 20px;
  border-radius: 50%;
  background: radial-gradient(ellipse at center, rgba(39, 19, 34, 0.24) 0%, rgba(39, 19, 34, 0) 72%);
  transition: transform 0.3s ease, opacity 0.3s ease;
  pointer-events: none;
}

.mascot-character-img {
  position: relative;
  z-index: 3;
  height: 316px;
  width: auto;
  object-fit: contain;
  transform-origin: 50% 90%;
  filter: drop-shadow(0 16px 24px rgba(39, 19, 34, 0.16));
  will-change: transform;
}

/* Floating Studio Badges on Stage */
.stage-float-chip {
  position: absolute;
  z-index: 4;
  background: rgba(255, 255, 255, 0.92);
  backdrop-filter: blur(8px);
  border: 1px solid #f3c1d8;
  border-radius: 12px;
  padding: 6px 10px;
  font-size: 11px;
  font-weight: 800;
  color: var(--text-primary);
  box-shadow: 0 8px 20px rgba(190, 62, 120, 0.1);
  pointer-events: none;
}

.stage-float-chip.chip-left {
  left: 6px;
  top: 56px;
  animation: chipBob 3.6s ease-in-out infinite;
}

.stage-float-chip.chip-right {
  right: 6px;
  bottom: 62px;
  animation: chipBob 4.1s ease-in-out infinite reverse;
}

@keyframes chipBob {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-6px); }
}

/* =========================================================
   5 EXPRESSIVE HARAKAT (MOVEMENTS & POSES) KEYFRAMES
   ========================================================= */

/* 1. Peace Welcome: Warm float + charismatic sway */
.pose-anim-welcome {
  animation: harakatWelcome 2.8s ease-in-out infinite;
}
@keyframes harakatWelcome {
  0%, 100% { transform: translateY(0) rotate(-1.6deg) scale(1); }
  50% { transform: translateY(-9px) rotate(2deg) scale(1.015); }
}

/* 2. Cool Shades VIP Boss: Confident lean + swagger nod */
.pose-anim-cool {
  animation: harakatCool 2.6s ease-in-out infinite;
}
@keyframes harakatCool {
  0%, 100% { transform: translateY(0) rotate(0deg) scale(1); }
  35% { transform: translateY(-5px) rotate(-2.4deg) scale(1.025); }
  70% { transform: translateY(-2px) rotate(1.6deg) scale(1.01); }
}

/* 3. Hype Jump: Energetic spring bounce in mid-air! */
.pose-anim-jump {
  animation: harakatJump 1.15s cubic-bezier(0.28, 0.84, 0.42, 1) infinite;
}
@keyframes harakatJump {
  0%, 100% { transform: translateY(4px) scale(1.03, 0.96); }
  45% { transform: translateY(-24px) scale(0.98, 1.04) rotate(1.5deg); }
  65% { transform: translateY(-20px) scale(1, 1.02) rotate(-1.5deg); }
}

.shadow-anim-jump {
  animation: shadowJump 1.15s cubic-bezier(0.28, 0.84, 0.42, 1) infinite;
}
@keyframes shadowJump {
  0%, 100% { transform: translateX(-50%) scale(1.05); opacity: 0.9; }
  45% { transform: translateX(-50%) scale(0.58); opacity: 0.38; }
}

/* 4. Alpha Print Inspector: Precision zoom-loupe scan */
.pose-anim-inspector {
  animation: harakatInspector 3.1s ease-in-out infinite;
}
@keyframes harakatInspector {
  0%, 100% { transform: translateX(0) rotate(0deg) scale(1); }
  30% { transform: translateX(-7px) translateY(-4px) rotate(-2.5deg) scale(1.03); }
  70% { transform: translateX(7px) translateY(-4px) rotate(2.5deg) scale(1.03); }
}

/* 5. Groove Dance: Rhythmic party step & finger-snap groove! */
.pose-anim-dance {
  animation: harakatDance 0.95s ease-in-out infinite;
}
@keyframes harakatDance {
  0%, 100% { transform: translateX(-8px) translateY(0) rotate(-4.5deg) scale(1.01); }
  25% { transform: translateX(0) translateY(-12px) rotate(0deg) scale(1.03); }
  50% { transform: translateX(8px) translateY(0) rotate(4.5deg) scale(1.01); }
  75% { transform: translateX(0) translateY(-10px) rotate(0deg) scale(1.03); }
}

/* Click Trick: 360 Spin Pop */
.pose-spin-trick {
  animation: harakatSpinPop 0.68s cubic-bezier(0.22, 1, 0.36, 1) 1 !important;
}
@keyframes harakatSpinPop {
  0% { transform: scale(0.92) rotateY(0deg) translateY(0); }
  45% { transform: scale(1.08) rotateY(180deg) translateY(-22px); }
  100% { transform: scale(1) rotateY(360deg) translateY(0); }
}

/* Sakura Burst Particle Emitter */
.mascot-fx-layer {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 5;
  overflow: hidden;
}

.sakura-burst-particle {
  position: absolute;
  left: 50%;
  top: 52%;
  font-size: 16px;
  pointer-events: none;
  animation: burstOut 0.95s cubic-bezier(0.16, 1, 0.3, 1) forwards;
}

@keyframes burstOut {
  0% { transform: translate(-50%, -50%) scale(0.4) rotate(0deg); opacity: 1; }
  100% { transform: translate(calc(-50% + var(--tx)), calc(-50% + var(--ty))) scale(1.15) rotate(var(--rot)); opacity: 0; }
}

/* 5-Pose Interactive Control Dock */
.mascot-pose-bar {
  position: relative;
  z-index: 4;
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
