    }
    if (!cipherBytes) return null;

    const keyBytes = sha256Bytes('VAULT-KEY:' + secretKey);
    const nonceBytes = sha256Bytes('VAULT-NONCE:' + itemId).slice(0, 12);
    const kdv = new DataView(keyBytes.buffer);
    const ndv = new DataView(nonceBytes.buffer);
    const base = new Uint32Array(16);
