    base[14] = ndv.getUint32(4, true);
    base[15] = ndv.getUint32(8, true);

    const out = new Uint8Array(cipherBytes.length);
    const w = new Uint32Array(16);
    const ks = new Uint8Array(64);
    const ksdv = new DataView(ks.buffer);
