  async function exportAndDownloadCleanPng(productId) {
    const prod = findProduct(productId);
    const masterUrl = unlockedBlobUrlCache[productId];
    if (!prod || !masterUrl) {
      showToast('🔒 Encrypted PNG: Complete real PayPal payment first to unlock.');
      return;
    }

    showToast('🌸 Exporting clean 300 DPI transparent PNG...');
    const img = new Image();
    img.decoding = 'sync';
    await new Promise((resolve, reject) => {
      img.onload = resolve;
      img.onerror = reject;
      img.src = masterUrl;
    });

    const canvas = document.createElement('canvas');
    canvas.width = img.naturalWidth;
    canvas.height = img.naturalHeight;
    const ctx = canvas.getContext('2d');
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.drawImage(img, 0, 0);

    const pngBlob = await new Promise((resolve) => canvas.toBlob(resolve, 'image/png'));
    const dlUrl = URL.createObjectURL(pngBlob);
    const a = document.createElement('a');
    a.href = dlUrl;
    a.download = prod.downloadFilename || `${productId}-ADZAK-ART.png`;
    document.body.appendChild(a);
    a.click();
    setTimeout(() => {
      a.remove();
      URL.revokeObjectURL(dlUrl);
    }, 3000);
    showToast(`✓ Downloading ${prod.downloadFilename}!`);
  }

