  function spawnMascotBurst(particles) {
    const layer = $('#mascotFxLayer');
    if (!layer) return;
    const list = particles || ['🌸', '✨', '💖', '🌸', '✨'];
    for (let i = 0; i < list.length; i++) {
      const span = document.createElement('span');
      span.className = 'sakura-burst-item';
      span.textContent = list[i];
      const angle = (Math.PI * 2 * i) / list.length + (Math.random() * 0.5 - 0.25);
      const dist = 75 + Math.random() * 65;
      span.style.left = `${48 + (Math.random() * 12 - 6)}%`;
      span.style.top = `${44 + (Math.random() * 12 - 6)}%`;
      span.style.setProperty('--dx', `${(Math.cos(angle) * dist).toFixed(0)}px`);
      span.style.setProperty('--dy', `${(Math.sin(angle) * dist - 35).toFixed(0)}px`);
      span.style.setProperty('--rot', `${Math.round(Math.random() * 90 - 45)}deg`);
      layer.appendChild(span);
      setTimeout(() => span.remove(), 1150);
    }
  }

