  async function unlockCurrentSelectionWithKey(validSecretKey, payerEmailOverride, payerNameOverride, explicitItemsOverride, isBundleOverride) {
    const savedSel = safeGetStorage(STORAGE_PENDING_SEL_KEY, null);
    const activeItems = getActiveCheckoutItems();
    const itemsToUnlock = (Array.isArray(explicitItemsOverride) && explicitItemsOverride.length > 0)
      ? explicitItemsOverride
      : ((activeItems && activeItems.length > 0)
          ? activeItems
          : ((savedSel && Array.isArray(savedSel.items) && savedSel.items.length > 0)
              ? savedSel.items
              : [{ productId: PRODUCTS[0].id, tierId: 'standard' }]));

    const unlockedOrderItems = [];
    for (const it of itemsToUnlock) {
      const p = findProduct(it.productId);
      if (!p) continue;
      const decryptedBytes = await chacha20DecryptItem(validSecretKey, p.id);
      if (!decryptedBytes) continue;
      await saveDecryptedBytesToIdb(p.id, decryptedBytes);
      unlockedOrderItems.push({
        productId: p.id,
        sku: p.sku,
        title: p.title,
        dimensions: p.dimensions,
        downloadFilename: p.downloadFilename,
        tierId: it.tierId || 'standard',
        tierName: it.tierId === 'unlimited' ? 'Unlimited Commercial Print Shop License' : 'Standard Print & Small Biz License'
      });
    }
    if (unlockedOrderItems.length === 0) return;

    const order = {
      orderId: generateOrderId(),
      buyerName: payerNameOverride || ($('#buyerNameInput')?.value || '').trim() || (savedSel && savedSel.buyerName) || 'PayPal Verified Buyer',
