  function mountPaypalHostedButton() {
    const isLocalFile = window.location.protocol === 'file:';
    const fileWarn = document.getElementById('fileProtocolWarning');
    if (fileWarn) fileWarn.hidden = !isLocalFile;
    if (isLocalFile || !window.paypal) return false;

    const smartWrap = document.getElementById('paypal-smart-buttons-container');
    const hostedWrap = document.getElementById('paypal-container-J2PB3BSV3DCC8');

    // Mode 1: Live Client ID -> In-Page PayPal Popup + Inline Card (100% Automatic Instant Unlock on Same Page!)
    if (PP_CFG.liveClientId && PP_CFG.liveClientId.trim().length > 15 && smartWrap && typeof window.paypal.Buttons === 'function') {
      if (hostedWrap) hostedWrap.innerHTML = '';
      smartWrap.innerHTML = '';
      try {
        window.paypal.Buttons({
          style: { layout: 'vertical', color: 'gold', shape: 'rect', label: 'pay' },
          createOrder: function (data, actions) {
            savePendingSelection();
            const { total } = calculateCheckoutTotal();
            const items = getActiveCheckoutItems();
            const desc = state.isBundleCheckout
              ? BUNDLE_OFFER.title
              : items.map((i) => getShortTitle(findProduct(i.productId) || { title: 'PNG' })).join(', ') + ' — ADZAK ART PNG';
            return actions.order.create({
              application_context: { shipping_preference: 'NO_SHIPPING' },
              purchase_units: [{
                description: desc.slice(0, 120),
                amount: { currency_code: 'USD', value: total.toFixed(2) }
              }]
            });
          },
          onApprove: async function (data, actions) {
            let payerEmail = '';
            let payerName = '';
            let approvedOk = Boolean(data && data.orderID);
            try {
              const details = await actions.order.capture();
              if (details) {
                approvedOk = true;
                payerEmail = details?.payer?.email_address || '';
                payerName = [details?.payer?.name?.given_name, details?.payer?.name?.surname].filter(Boolean).join(' ');
              }
            } catch (capErr) {
              console.warn('Capture hold/review note:', capErr);
            }
            if (approvedOk) {
              const internalKey = ['ADZAK-PP9X', '4M7K2W8Q5L', '3N6R'].join('');
              await unlockCurrentSelectionWithKey(internalKey, payerEmail, payerName);
            }
          }
        }).render('#paypal-smart-buttons-container');
        return true;
      } catch (e) {
        console.error('Smart Buttons error:', e);
      }
    }

    // Mode 2: HostedButtons fallback (J2PB3BSV3DCC8)
    if (hostedWrap && typeof window.paypal.HostedButtons === 'function') {
      const activeBtnId = PP_CFG.hostedButtonId || 'J2PB3BSV3DCC8';
      if (renderedHostedBtnId === activeBtnId && hostedWrap.children.length > 0) return true;
      hostedWrap.innerHTML = '';
      try {
        window.paypal.HostedButtons({ hostedButtonId: activeBtnId }).render('#paypal-container-J2PB3BSV3DCC8');
        renderedHostedBtnId = activeBtnId;
        const fb = document.getElementById('directPaypalPayBtn');
        if (fb) { fb.style.marginTop = '8px'; fb.style.padding = '9px 14px'; fb.style.fontSize = '13px'; }
        return true;
      } catch (_) {}
    }
    return false;
  }

