  function getActiveCheckoutItems() {
    return state.checkoutMode === 'cart' ? state.cart : state.directCheckoutItems;
  }

  function calculateCheckoutTotal() {
    const items = getActiveCheckoutItems();
    let subtotal = 0;
    if (state.isBundleCheckout) subtotal = Number(BUNDLE_OFFER.price);
    else {
      for (const item of items) {
        const p = findProduct(item.productId);
        if (p) subtotal += Number(p.price) + getTierExtra(item.tierId);
      }
    }
    if (PP_CFG && PP_CFG.testCentMode) {
      const testAmt = Number(PP_CFG.testCentAmount || 0.01);
      return { subtotal, discount: Math.max(0, +(subtotal - testAmt).toFixed(2)), total: testAmt, isTestCent: true };
    }
    let discount = 0;
    if (state.appliedCoupon) discount = +(subtotal * (state.appliedCoupon.percentOff / 100)).toFixed(2);
    return { subtotal, discount, total: Math.max(0.5, +(subtotal - discount).toFixed(2)), isTestCent: false };
  }

