            </div>
          </div>
          <div class="co-item-right"><strong class="co-item-price">${formatUSD(BUNDLE_OFFER.price)}</strong></div>
        </div>`;
    } else {
      listEl.innerHTML = items.map((item, idx) => {
        const p = findProduct(item.productId);
        if (!p) return '';
        const itemPrice = +(Number(p.price) + getTierExtra(item.tierId)).toFixed(2);
        const tierLabel = item.tierId === 'unlimited' ? 'Unlimited Print Shop License' : 'Standard Print License';
