  function generateOrderId() {
    const chars = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
    let s = 'ADZ-';
    for (let i = 0; i < 6; i++) s += chars[Math.floor(Math.random() * chars.length)];
    return s;
  }

  // Cryptographic PayPal Auto-Return Verification (supports signed dynamic return pp_claim + pp_sig AND static pp_unlock)
  async function verifyCryptographicPaypalReturn() {
    const params = new URLSearchParams(window.location.search);

    if (params.get('pp_cancel')) {
      if (window.location.protocol.startsWith('http')) {
        window.history.replaceState({}, '', window.location.pathname);
      }
      showToast('Payment cancelled on PayPal — your PNG vault remains locked.');
      return;
    }

    const claimB64 = (params.get('pp_claim') || '').trim();
    const claimSig = (params.get('pp_sig') || '').trim();
    if (claimB64 && claimSig) {
      if (window.location.protocol.startsWith('http')) {
        window.history.replaceState({}, '', window.location.pathname);
      }
      const internalKey = ['ADZAK-PP9X', '4M7K2W8Q5L', '3N6R'].join('');
      const expectedSig = bytesToHex(sha256Bytes('ADZAK-SIGNED-RETURN:' + claimB64 + ':' + internalKey)).slice(0, 32);
      if (claimSig !== expectedSig) {
        showToast('🔒 Invalid or forged payment return signature.');
        return;
      }
      try {
        const b64Std = claimB64.replace(/-/g, '+').replace(/_/g, '/');
        const padded = b64Std + '='.repeat((4 - (b64Std.length % 4)) % 4);
        const bin = atob(padded);
        const bytes = new Uint8Array(bin.length);
        for (let k = 0; k < bin.length; k++) bytes[k] = bin.charCodeAt(k);
        const payload = JSON.parse(new TextDecoder().decode(bytes));
        const nowSec = Math.floor(Date.now() / 1000);
        if (!payload || !payload.t || Math.abs(nowSec - Number(payload.t)) > 14400) {
          showToast('🔒 Expired payment return session.');
          return;
        }
        const explicitItems = Array.isArray(payload.i)
          ? payload.i.map((x) => ({ productId: x.p, tierId: x.t || 'standard' }))
          : null;
        await unlockCurrentSelectionWithKey(
          internalKey,
          payload.e || '',
          payload.n || '',
          explicitItems,
          Boolean(payload.b)
        );
        return;
      } catch (err) {
        console.error('Return decode error:', err);
        showToast('🔒 Invalid payment return payload.');
        return;
      }
    }

    const ppKey = (params.get('pp_unlock') || params.get('pp_key') || '').trim();
    if (!ppKey) return;

    if (window.location.protocol.startsWith('http')) {
      window.history.replaceState({}, '', window.location.pathname);
    }

    const candidateHash = bytesToHex(sha256Bytes('VERIFY:' + ppKey));
    if (candidateHash !== PAYPAL_RETURN_VERIFY_SHA256) {
      showToast('🔒 Invalid or unauthorized payment return token.');
      return;
    }

    await unlockCurrentSelectionWithKey(ppKey, '', '');
  }

