      const buyBtn = e.target.closest('[data-action="buy-single"]');
      if (buyBtn) { openSingleCheckout(buyBtn.dataset.id, 'standard'); return; }
      const cartBtn = e.target.closest('[data-action="cart"]');
      if (cartBtn) {
        const id = cartBtn.dataset.id;
        if (state.cart.some((c) => c.productId === id)) openCartCheckout();
        else {
          state.cart.push({ productId: id, tierId: 'standard' });
          persistCart();
          renderCatalogGrid();
          showToast('🌸 Added to Cart');
